// Runnable demo of core API Gateway functions in plain Java.
package com.bank.gateway.demo;

import java.util.*;
import java.util.logging.*;

public class GatewayDemo {
    private static final Logger log = Logger.getLogger("ApiGateway");
    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler();
        h.setLevel(Level.ALL); h.setFormatter(new GwLogFormatter());
        log.addHandler(h); log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        ApiGateway gateway = new ApiGateway();

        log.info("=== Routing + Auth ===");
        gateway.handle(new GatewayRequest("/api/v1/accounts/SAV2001", "rajesh", "valid-token"));

        log.info("=== Auth rejection ===");
        gateway.handle(new GatewayRequest("/api/v1/payments/pay", "priya", "bad-token"));

        log.info("=== Rate limiting (flood) ===");
        for (int i = 1; i <= 7; i++) {
            gateway.handle(new GatewayRequest("/api/v1/payments/pay", "flooder", "valid-token"));
        }

        log.info("=== Aggregation (dashboard) ===");
        String dash = gateway.dashboard("SAV2001", "valid-token");
        log.info(() -> "Aggregated: " + dash);
    }
}

