class BackendService {
    String account(String id) { return "{\"id\":\"" + id + "\",\"holder\":\"Rajesh Kumar\",\"balance\":1000000}"; }
    String card(String id)    { return "{\"card\":\"**** 4021\",\"status\":\"ACTIVE\"}"; }
