// ─── Would be in core/ApiGateway.java ───
class ApiGateway {
    private static final Logger log = Logger.getLogger("ApiGateway");
    private final BackendService backend = new BackendService();
    private final Map<String, String> routes = new LinkedHashMap<>();
    private final Map<String, TokenBucket> limiters = new HashMap<>();

    ApiGateway() {
        routes.put("/api/v1/accounts", "account-service");
        routes.put("/api/v1/payments", "payment-service");
        routes.put("/api/v1/cards", "card-service");
    }

    // Main request path: authenticate, rate limit, route, load balance, respond.
    String handle(GatewayRequest req) {
        if (!authenticate(req.token)) {
            log.warning(() -> "401 Unauthorized for client=" + req.clientId);
            return "401";
        }
        if (!allow(req.clientId)) {
            log.warning(() -> "429 Too Many Requests client=" + req.clientId);
            return "429";
        }
        String service = route(req.path);
        if (service == null) { log.warning("404 no route"); return "404"; }
        String instance = loadBalance(service);
        log.info(() -> "Routed " + req.path + " -> " + instance);
        return dispatch(service, req.path);
    }

    // Aggregation: combine account + card into one dashboard payload.
    String dashboard(String accountId, String token) {
        if (!authenticate(token)) return "401";
        String acct = backend.account(accountId);
        String card = backend.card(accountId);
        return "{\"account\":" + acct + ",\"card\":" + card + "}";
    }

    private boolean authenticate(String token) { return "valid-token".equals(token); }

    private boolean allow(String clientId) {
        return limiters.computeIfAbsent(clientId, k -> new TokenBucket(5)).tryConsume();
    }

    private String route(String path) {
        for (Map.Entry<String, String> e : routes.entrySet())
            if (path.startsWith(e.getKey())) return e.getValue();
        return null;
    }

    private String loadBalance(String service) {
        int instance = 1 + new Random().nextInt(3); // 3 instances
        return service + "#" + instance;
    }

    private String dispatch(String service, String path) {
        switch (service) {
            case "account-service": return backend.account("SAV2001");
            case "payment-service": return backend.payment("x");
            case "card-service":    return backend.card("x");
            default: return "404";
        }
    }
}

// ─── Would be in core/TokenBucket.java ───
class TokenBucket {
    private int tokens; private final int capacity;
    TokenBucket(int capacity) { this.capacity = capacity; this.tokens = capacity; }
    synchronized boolean tryConsume() {
        if (tokens > 0) { tokens--; return true; }
        return false;
    }
}

// ─── Would be in GwLogFormatter.java ───
class GwLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), formatMessage(r));
    }
}
